-- Generated from the local school migrations. Preview-only namespace, no live data.
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lead_funnel(id TEXT PRIMARY KEY, direction TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, enrolled_student_id TEXT, assigned_teacher_id TEXT);
CREATE TABLE IF NOT EXISTS school_guardians(parent_id TEXT NOT NULL, student_id TEXT NOT NULL, PRIMARY KEY(parent_id,student_id));
CREATE TABLE IF NOT EXISTS school_teacher_students(teacher_id TEXT NOT NULL, student_id TEXT NOT NULL, PRIMARY KEY(teacher_id,student_id));
CREATE TABLE IF NOT EXISTS school_groups(id TEXT PRIMARY KEY, title TEXT NOT NULL, teacher_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_group_members(group_id TEXT NOT NULL REFERENCES school_groups(id), student_id TEXT NOT NULL, PRIMARY KEY(group_id, student_id));
CREATE TABLE IF NOT EXISTS school_courses(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, summary TEXT NOT NULL, level TEXT NOT NULL DEFAULT 'A1', audience TEXT NOT NULL DEFAULT 'Не уточнена', topic TEXT NOT NULL DEFAULT 'Начало', format TEXT NOT NULL DEFAULT 'Самостоятельный демомодуль', status TEXT NOT NULL DEFAULT 'preparing', publication TEXT NOT NULL DEFAULT 'draft', demo INTEGER NOT NULL DEFAULT 0, owner_id TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS school_modules(id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES school_courses(id), title TEXT NOT NULL, position INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS school_lessons(id TEXT PRIMARY KEY, module_id TEXT NOT NULL REFERENCES school_modules(id), title TEXT NOT NULL, goal TEXT NOT NULL, blocks TEXT NOT NULL CHECK(json_valid(blocks)), exercises TEXT NOT NULL CHECK(json_valid(exercises)), homework TEXT NOT NULL DEFAULT '', teacher_notes TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL, publication TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS school_entitlements(id TEXT PRIMARY KEY, student_id TEXT NOT NULL, course_id TEXT NOT NULL REFERENCES school_courses(id), source TEXT NOT NULL, granted_by TEXT NOT NULL, expires_at TEXT, revoked_at TEXT, UNIQUE(student_id,course_id,source));
CREATE TABLE IF NOT EXISTS school_completions(student_id TEXT NOT NULL, lesson_id TEXT NOT NULL REFERENCES school_lessons(id), created_at TEXT NOT NULL, PRIMARY KEY(student_id,lesson_id));
CREATE TABLE IF NOT EXISTS school_attempts(id TEXT PRIMARY KEY, student_id TEXT NOT NULL, lesson_id TEXT NOT NULL, exercise_id TEXT NOT NULL, exercise_version INTEGER NOT NULL, answers TEXT NOT NULL, score INTEGER, feedback TEXT NOT NULL, request_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(student_id,request_key));
CREATE TABLE IF NOT EXISTS school_submissions(id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL, student_id TEXT NOT NULL, attempt_no INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','submitted','returned','checked')), upload_id TEXT, due_at TEXT, submitted_at TEXT, version INTEGER NOT NULL DEFAULT 1, assignment_id TEXT REFERENCES school_assignments(id), UNIQUE(lesson_id,student_id,attempt_no));
CREATE TABLE IF NOT EXISTS school_events(id TEXT PRIMARY KEY, title TEXT NOT NULL, teacher_id TEXT NOT NULL, student_id TEXT, group_id TEXT, starts_at TEXT NOT NULL, timezone TEXT NOT NULL, meeting_url TEXT, status TEXT NOT NULL DEFAULT 'scheduled');
CREATE TABLE IF NOT EXISTS school_materials(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, relative_path TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', description_source TEXT NOT NULL, format TEXT NOT NULL DEFAULT '', bytes INTEGER, checksum TEXT, processing TEXT CHECK(processing IN ('unprocessed','partial','full') OR processing IS NULL), legacy_processed TEXT, editorial TEXT NOT NULL DEFAULT 'unchecked', publication TEXT NOT NULL DEFAULT 'draft', rights TEXT NOT NULL DEFAULT 'unknown', privacy TEXT NOT NULL DEFAULT 'internal', topic TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT '', audience TEXT NOT NULL DEFAULT '', skills TEXT NOT NULL DEFAULT '', instructions TEXT NOT NULL DEFAULT '', related TEXT NOT NULL DEFAULT '[]', storage_key TEXT, missing INTEGER NOT NULL DEFAULT 1, rights_note TEXT NOT NULL DEFAULT '', original_path TEXT NOT NULL DEFAULT '', file_id TEXT REFERENCES school_files(id), UNIQUE(source_id,relative_path));
CREATE TABLE IF NOT EXISTS school_lesson_materials(lesson_id TEXT NOT NULL REFERENCES school_lessons(id), material_id TEXT NOT NULL REFERENCES school_materials(id), PRIMARY KEY(lesson_id,material_id));
CREATE TABLE IF NOT EXISTS school_favorites(student_id TEXT NOT NULL, material_id TEXT NOT NULL REFERENCES school_materials(id), PRIMARY KEY(student_id,material_id));
CREATE TABLE IF NOT EXISTS school_import_runs(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, digest TEXT NOT NULL, report TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_assignments(id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL UNIQUE REFERENCES school_lessons(id), title TEXT NOT NULL, instructions TEXT NOT NULL, due_at TEXT);
CREATE TABLE IF NOT EXISTS school_audit(id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_files(id TEXT PRIMARY KEY, checksum TEXT NOT NULL UNIQUE, bytes INTEGER NOT NULL, storage_key TEXT NOT NULL, format TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_archive_folders(id TEXT PRIMARY KEY,parent_id TEXT,title TEXT NOT NULL,relative_path TEXT NOT NULL,depth INTEGER NOT NULL,purpose TEXT NOT NULL,source_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_archive_materials(material_id TEXT PRIMARY KEY,folder_id TEXT NOT NULL,file_id TEXT NOT NULL,processing TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)));
CREATE TABLE IF NOT EXISTS school_archive_programs(course_id TEXT PRIMARY KEY,readiness TEXT NOT NULL,kind TEXT NOT NULL,provenance TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)));
CREATE TABLE IF NOT EXISTS school_archive_module_materials(module_id TEXT NOT NULL,material_id TEXT NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(module_id,material_id));
CREATE TABLE IF NOT EXISTS school_archive_batches(digest TEXT NOT NULL,part TEXT NOT NULL,checksum TEXT NOT NULL,PRIMARY KEY(digest,part));
CREATE TABLE IF NOT EXISTS school_archive_import_runs(digest TEXT PRIMARY KEY,state TEXT NOT NULL,report TEXT NOT NULL CHECK(json_valid(report)),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS school_entitlements_student ON school_entitlements(student_id,course_id,revoked_at);
CREATE INDEX IF NOT EXISTS school_submissions_status ON school_submissions(status,student_id);
CREATE INDEX IF NOT EXISTS school_materials_catalog ON school_materials(publication,rights,editorial,topic);
CREATE INDEX IF NOT EXISTS school_lessons_module ON school_lessons(module_id,position);
CREATE INDEX IF NOT EXISTS school_audit_actor ON school_audit(actor_id,created_at);
CREATE INDEX IF NOT EXISTS school_archive_folders_parent ON school_archive_folders(parent_id);
CREATE INDEX IF NOT EXISTS school_archive_materials_folder ON school_archive_materials(folder_id);
CREATE TABLE IF NOT EXISTS pd_users(id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student','parent')), timezone TEXT NOT NULL DEFAULT 'Europe/Moscow', notifications INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS pd_sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES pd_users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pd_leads(id TEXT PRIMARY KEY, name TEXT NOT NULL, contact TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', request_key TEXT NOT NULL UNIQUE, ip_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pd_responses(id TEXT PRIMARY KEY, student_id TEXT NOT NULL, text TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS pd_reviews(id TEXT PRIMARY KEY, submission_id TEXT NOT NULL, author_id TEXT NOT NULL, text TEXT NOT NULL, decision TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pd_notes(student_id TEXT PRIMARY KEY, text TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS pd_uploads(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, storage_key TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pd_credentials(user_id TEXT PRIMARY KEY REFERENCES pd_users(id), login TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pd_login_attempts(ip_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS pd_leads_rate ON pd_leads(ip_hash,created_at);
CREATE INDEX IF NOT EXISTS pd_login_attempts_ip ON pd_login_attempts(ip_hash,created_at);
